window.MG_LAZY_DATA["data/lazy/resources/security-v26-067-fd985c21f0ae22e0.json"]={sha256:"fd985c21f0ae22e0f1aa08866fa53a184bf424ffc97e20a4fe7f8a79a2da7c46",value:{"sources":[{"id":"v26-case-37f64e8717c0d3af","url":"https://github.com/gitleaks/gitleaks","title":"Gitleaks secret detection","titleEn":"Gitleaks secret detection","publisher":"Gitleaks","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-067","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-067","related":[{"id":"security-v26-068","referenceUrls":["https://docs.docker.com/engine/security/rootless/"],"title":"Docker Rootless：容器身分與主機權限邊界","titleEn":"Docker Rootless: container identities and host privilege boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：交付15筆遮罩紀錄、5筆窄範圍例外、10筆處置狀態及新樣本回歸結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver fifteen redacted records, five narrow exceptions, ten response states and new-fixture regression results.","difference":"分清容器內UID、主機UID映射、capability與掛載可寫性，列出仍存在的信任邊界。","differenceEn":"Separate container UID, host UID mapping, capabilities and writable mounts, listing remaining trust boundaries.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["處置完成率以已確認需處置項為分母；刪除檔案不等於已撤銷憑證。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成掃描有15筆發現，5筆為核准測試字串，10筆假設需處置；其中7筆有撤銷與驗證證據。 處置完成率7/10=70%，不能用7/15評估此佇列。","本課權限面積以允許能力數×可寫掛載數作粗略代理；不是可量測的入侵機率。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 配置A允許12項能力及4個可寫掛載；配置B只需3項能力及2個可寫掛載。 代理量A=48、B=6，縮減(48−6)/48=87.5%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Response completion uses confirmed actionable findings as its denominator; deleting a file does not revoke a credential. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic scan has fifteen findings, five approved test strings and ten hypothetically actionable cases; seven have revocation and verification evidence. Completion rate=7/10=70%, not 7/15 for this queue.","A teaching privilege-surface proxy multiplies allowed capabilities by writable mounts; it is not an intrusion probability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Configuration A allows twelve capabilities and four writable mounts; B needs three capabilities and two writable mounts. The proxy falls from 48 to 6, a reduction of 87.5%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-077","referenceUrls":["https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-log-file-validation-intro.html"],"title":"AWS CloudTrail：摘要鏈與完整性驗證","titleEn":"AWS CloudTrail: digest chains and integrity validation","why":"用兩課的可觀察驗收條件比較模型邊界：交付15筆遮罩紀錄、5筆窄範圍例外、10筆處置狀態及新樣本回歸結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver fifteen redacted records, five narrow exceptions, ten response states and new-fixture regression results.","difference":"區分啟用摘要產生與實際執行驗證，檢查日誌摘要、簽署信任與前一摘要連結。","differenceEn":"Distinguish enabling digest delivery from performing validation; inspect log hashes, signer trust and previous-digest links.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["處置完成率以已確認需處置項為分母；刪除檔案不等於已撤銷憑證。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成掃描有15筆發現，5筆為核准測試字串，10筆假設需處置；其中7筆有撤銷與驗證證據。 處置完成率7/10=70%，不能用7/15評估此佇列。","完整性驗證覆蓋=已驗證時段/應有時段；雜湊相符不單獨證明來源身分或完整收集。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 24個小時應各有一份摘要；收到23份，其中22份連結與日誌驗證通過。 已驗證覆蓋22/24=91.6667%；缺1份與失敗1份需分開列。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Response completion uses confirmed actionable findings as its denominator; deleting a file does not revoke a credential. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic scan has fifteen findings, five approved test strings and ten hypothetically actionable cases; seven have revocation and verification evidence. Completion rate=7/10=70%, not 7/15 for this queue.","Integrity-validation coverage is verified periods divided by expected periods; matching hashes alone prove neither source identity nor complete collection. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Twenty-four hourly digests are expected; twenty-three arrive, and twenty-two pass link and log validation. Verified coverage=22/24=91.6667%; distinguish one missing digest from one validation failure.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-7e61efb4dd5933bf","url":"https://docs.docker.com/engine/security/rootless/","title":"Docker rootless mode","titleEn":"Docker rootless mode","publisher":"Docker","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-eee83c3856f83a67","url":"https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-log-file-validation-intro.html","title":"Validating CloudTrail log integrity","titleEn":"Validating CloudTrail log integrity","publisher":"AWS","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
